insert = "        if plain:\n            rows.append([plain, \"\"]) \n    return rows\n\n\ndef _md_to_html(markdown: str) -> str:\n    \"\"\"极简 Markdown → HTML: 标题/表格/段落/列表/引用 (自包含, 无外部依赖)\"\"\"\n    import html as _html\n    lines = markdown.split(\"\\n\")\n    out = []\n    in_table = False\n    for raw in lines:\n        line = raw.rstrip()\n        if not line:\n            in_table = False\n            out.append(\"\")\n            continue\n        h = re.match(r'^(#{1,4})\\s+(.+)', line)\n        if h:\n            in_table = False\n            lvl = len(h.group(1))\n            out.append(f\"<h{lvl}>{_html.escape(h.group(2))}</h{lvl}>\")\n            continue\n        if line.startswith(\"> \"):\n            in_table = False\n            out.append(f\"<blockquote>{_html.escape(line[2:])}</blockquote>\")\n            continue\n        if line.startswith(\"- \"):\n            in_table = False\n            out.append(f\"<li>{_html.escape(line[2:])}</li>\")\n            continue\n        if line.startswith(\"|\") and line.endswith(\"|\"):\n            cells = [c.strip().strip(\"`\") for c in line.strip(\"|\").split(\"|\")]\n            if all(c in (\"\", \"---\", \"----\", \"-----\", \"------\") for c in cells):\n                continue\n            if not in_table:\n                out.append(\"<table>\")\n                in_table = True\n            tag = \"th\" if not any(\"<tr>\" in o for o in out[-3:]) else \"td\"\n            out.append(\"<tr>\" + \"\".join(f\"<{tag}>{_html.escape(c)}</{tag}>\" for c in cells) + \"</tr>\")\n            continue\n        in_table = False\n        plain = re.sub(r'[*_`>#-]', \"\", line).strip()\n        if plain:\n            out.append(f\"<p>{_html.escape(plain)}</p>\")\n    if in_table:\n        out.append(\"</table>\")\n    return \"\\n\".join(out)\n\n\ndef export_html(path, markdown, title=\"量化日历报表\"):\n    \"\"\"V5.3.0 (T-5.3.5.5 / FR-5.3.5.5): 报表 HTML 导出 — 自包含文件, 可浏览器直接打开\"\"\"\n    body = _md_to_html(markdown)\n    doc = f\"\"\"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<title>{_html_escape(title)}</title>\n<style>\nbody {{ font-family: -apple-system, 'PingFang SC', 'Microsoft YaHei', sans-serif; max-width: 960px; margin: 24px auto; padding: 0 16px; color: #1f2937; line-height: 1.6; }}\nh1 {{ font-size: 22px; border-bottom: 2px solid #e5e7eb; padding-bottom: 8px; }}\nh2 {{ font-size: 18px; margin-top: 24px; }}\nh3 {{ font-size: 15px; }}\ntable {{ border-collapse: collapse; width: 100%; margin: 12px 0; font-size: 13px; }}\nth, td {{ border: 1px solid #e5e7eb; padding: 6px 10px; text-align: left; }}\nth {{ background: #f9fafb; font-weight: 600; }}\ntr:nth-child(even) td {{ background: #fafafa; }}\nblockquote {{ border-left: 3px solid #d1d5db; margin: 8px 0; padding: 4px 12px; color: #6b7280; }}\np, li {{ font-size: 14px; }}\n</style>\n</head>\n<body>\n{body}\n</body>\n</html>\"\"\".format(title=title, body=body)\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        f.write(doc)\n    return {\"format\": \"html\", \"path\": path}\n\n\ndef _html_escape(s: str) -> str:\n    import html as _h\n    return _h.escape(str(s))\n\n\ndef export_report(markdown, fmt, path):"
